#!/usr/bin/env swift
// Turns the International ISBN Agency's range message into
// Sources/BuchhalterCore/Logic/ISBNRanges.swift.
//
//   curl -o build/RangeMessage.xml https://www.isbn-international.org/export_rangemessage.xml
//   swift Scripts/make-isbn-ranges.swift build/RangeMessage.xml Sources/BuchhalterCore/Logic/ISBNRanges.swift
//
// `make isbn-ranges` runs both steps. The generated file is committed, so the
// build never needs the network.

import Foundation

/// Collects `<Prefix>` and `<Rule>` values of every `<EAN.UCC>` and `<Group>`.
final class RangeParser: NSObject, XMLParserDelegate {
    struct Entry { var prefix = ""; var rules: [(range: String, length: String)] = [] }

    var date = ""
    var eanPrefixes: [Entry] = []
    var groups: [Entry] = []
    private var current: Entry?
    private var isGroup = false
    private var range = ""
    private var length = ""
    private var text = ""

    func parser(_ parser: XMLParser, didStartElement name: String, namespaceURI: String?, qualifiedName: String?, attributes: [String: String] = [:]) {
        text = ""
        switch name {
        case "EAN.UCC": current = Entry(); isGroup = false
        case "Group": current = Entry(); isGroup = true
        default: break
        }
    }

    func parser(_ parser: XMLParser, foundCharacters string: String) { text += string }

    func parser(_ parser: XMLParser, didEndElement name: String, namespaceURI: String?, qualifiedName: String?) {
        let value = text.trimmingCharacters(in: .whitespacesAndNewlines)
        switch name {
        case "MessageDate": date = value
        case "Prefix": current?.prefix = value
        case "Range": range = value
        case "Length": length = value
        case "Rule": current?.rules.append((range, length))
        case "EAN.UCC", "Group":
            if let entry = current { if isGroup { groups.append(entry) } else { eanPrefixes.append(entry) } }
            current = nil
        default: break
        }
    }
}

let arguments = CommandLine.arguments
guard arguments.count == 3 else {
    FileHandle.standardError.write(Data("usage: make-isbn-ranges.swift <RangeMessage.xml> <output.swift>\n".utf8))
    exit(2)
}
guard let parser = XMLParser(contentsOf: URL(fileURLWithPath: arguments[1])) else {
    FileHandle.standardError.write(Data("cannot read \(arguments[1])\n".utf8))
    exit(1)
}
let delegate = RangeParser()
parser.delegate = delegate
guard parser.parse(), !delegate.groups.isEmpty else {
    FileHandle.standardError.write(Data("cannot parse \(arguments[1]): \(parser.parserError.map(String.init(describing:)) ?? "no groups")\n".utf8))
    exit(1)
}

/// One line per prefix: "978-3 0000000-0299999:2 0300000-0339999:3 …".
/// Rules with length 0 are unassigned ranges and are left out.
func lines(_ entries: [RangeParser.Entry]) -> String {
    entries.map { entry in
        ([entry.prefix] + entry.rules.filter { $0.length != "0" }.map { "\($0.range):\($0.length)" })
            .joined(separator: " ")
    }
    .joined(separator: "\n")
}

let output = """
// Generated by Scripts/make-isbn-ranges.swift from the International ISBN
// Agency's range message of \(delegate.date). Do not edit; run `make isbn-ranges`.

/// The ISBN ranges as text, parsed once by `ISBNHyphenation`. A Swift array
/// literal of this size would slow the compiler down.
enum ISBNRanges {
    /// The EAN prefixes (978, 979): which 7-digit ranges have which group length.
    static let prefixes = \"\"\"
\(lines(delegate.eanPrefixes))
\"\"\"

    /// The registration groups: which 7-digit ranges have which registrant length.
    static let groups = \"\"\"
\(lines(delegate.groups))
\"\"\"
}

"""
try output.write(toFile: arguments[2], atomically: true, encoding: .utf8)
print("\(delegate.eanPrefixes.count) prefixes, \(delegate.groups.count) groups → \(arguments[2])")
